WITH cleaned AS (SELECT *, COALESCE(duration_sec, 0) AS duration_sec_filled FROM web_events WHERE page IS NOT NULL AND event_time >= TO_TIMESTAMP('2023-08-08 09:00:00')), ranked AS (SELECT id, event_type, duration_sec FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page, event_type ORDER BY duration_sec_filled DESC, id) AS rn FROM cleaned) ranked WHERE rn = 1), filtered AS (SELECT *, SUBSTRING(event_type, 1, 2) AS event_type_prefix FROM ranked WHERE event_type = 'purchase'), latest AS (SELECT id, duration_sec, event_type_prefix FROM (SELECT *, RANK() OVER (PARTITION BY event_type ORDER BY duration_sec DESC NULLS FIRST) AS rank_in_group FROM filtered) t WHERE rank_in_group = 1), with_windows AS (SELECT id, event_type_prefix, ROW_NUMBER() OVER w_recent AS row_seq, LAST_VALUE(duration_sec) IGNORE NULLS OVER w_hist AS last_known_duration_sec, NTILE(3) OVER w_recent AS duration_sec_bucket, SUM(duration_sec) OVER w_hist AS cumulative_duration_sec FROM latest WINDOW w_recent AS (ORDER BY duration_sec DESC, id), w_hist AS (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), filtered_web_events AS (SELECT *, duration_sec_bucket - last_known_duration_sec AS duration_sec_bucket_minus_last_known_duration_sec FROM with_windows WHERE row_seq != 4), valid AS (SELECT *, ROUND(row_seq, 2) AS row_seq_rounded, row_seq * cumulative_duration_sec AS row_seq_times_cumulative_duration_sec FROM filtered_web_events WHERE duration_sec_bucket < 6) SELECT id, event_type_prefix, row_seq, last_known_duration_sec, duration_sec_bucket, cumulative_duration_sec, duration_sec_bucket_minus_last_known_duration_sec, row_seq_rounded, row_seq_times_cumulative_duration_sec FROM valid ORDER BY last_known_duration_sec;
